import re
def extract_title_heading_buggy(heading_text):
    def is_allowed(c):
        if c.isalnum() or c in "-_/:@+=$%&'~":
            return True
        if c.isalpha():
            return True
        return False
    def valid_tag(tag):
        if not tag:
            return False
        if tag.isdigit():
            return False
        return True
    s=heading_text
    out=""
    i=0
    while i < len(s):
        if s[i]=='#' and i+1 < len(s) and s[i+1] not in (' ', '\t', '\n', '\r', ',', '.', '!', '?', ';', '(', ')', '[', ']', '"', '*', '^', '`', '{', '}', '|', '\\', '<', '>', '#'):
            if i>0 and is_allowed(s[i-1]):
                out+=s[i]
                i+=1
                continue
            j=i+1
            while j < len(s) and is_allowed(s[j]):
                j+=1
            tag=s[i+1:j]
            if not valid_tag(tag):
                out+=s[i]
                i+=1
                continue
            k=j
            while k < len(s) and s[k].isspace():
                k+=1
            at_end = (k>=len(s))
            if at_end:
                out+=tag[-1] if tag else ""
            else:
                out+=""
            i=j
        else:
            out+=s[i]
            i+=1
    return out.strip()

tests=[
    "Second with #tag",
    "Hello #world",
    "A #ab",
    "Title with #tag and #another"
]
for t in tests:
    print(t, "=>", repr(extract_title_heading_buggy(t)))
